import ExpoModulesCore
import Speech

private let PARTIAL_TRANSCRIPT_EVENT = "onPartialTranscript"

internal final class SampleAudioUnavailableException: Exception {
  override var reason: String {
    "Sample audio file is missing from the app bundle."
  }
}

internal final class RecognizerUnavailableException: Exception {
  override var reason: String {
    "Speech recognizer is not available for the current locale."
  }
}

internal final class TranscriptionInProgressException: Exception {
  override var reason: String {
    "A transcription is already running."
  }
}

public class SpeechRecognizerModule: Module {
  private var recognitionTask: SFSpeechRecognitionTask?

  public func definition() -> ModuleDefinition {
    Name("SpeechRecognizerModule")

    Events(PARTIAL_TRANSCRIPT_EVENT)

    AsyncFunction("requestAuthorization") { () -> String in
      let status = await withCheckedContinuation { (continuation: CheckedContinuation<SFSpeechRecognizerAuthorizationStatus, Never>) in
        SFSpeechRecognizer.requestAuthorization { status in
          continuation.resume(returning: status)
        }
      }
      return SpeechRecognizerModule.authorizationStatusString(status)
    }

    Function("getAuthorizationStatus") { () -> String in
      SpeechRecognizerModule.authorizationStatusString(SFSpeechRecognizer.authorizationStatus())
    }

    AsyncFunction("transcribeSample") { (promise: Promise) in
      self.transcribeSample(promise: promise)
    }
  }

  private func transcribeSample(promise: Promise) {
    guard recognitionTask == nil else {
      promise.reject(TranscriptionInProgressException())
      return
    }
    guard let url = Bundle(for: SpeechRecognizerModule.self).url(forResource: "sample", withExtension: "wav") else {
      promise.reject(SampleAudioUnavailableException())
      return
    }
    guard let recognizer = SFSpeechRecognizer(), recognizer.isAvailable else {
      promise.reject(RecognizerUnavailableException())
      return
    }

    let request = SFSpeechURLRecognitionRequest(url: url)
    request.shouldReportPartialResults = true

    recognitionTask = recognizer.recognitionTask(with: request) { [weak self] result, error in
      guard let self else { return }
      if let error {
        self.recognitionTask = nil
        promise.reject(error)
        return
      }
      guard let result else { return }

      self.sendEvent(PARTIAL_TRANSCRIPT_EVENT, ["transcript": result.bestTranscription.formattedString])

      if result.isFinal {
        self.recognitionTask = nil
        promise.resolve(result.bestTranscription.formattedString)
      }
    }
  }

  private static func authorizationStatusString(_ status: SFSpeechRecognizerAuthorizationStatus) -> String {
    switch status {
    case .notDetermined:
      return "notDetermined"
    case .authorized:
      return "authorized"
    case .denied, .restricted:
      return "denied"
    @unknown default:
      return "notDetermined"
    }
  }
}

